    {
      "document_id": "2003",
      "label": "0",
      "explanation": "Senator Clinton announces a new Predator squadron for New York but does not state her personal involvement in securing it (she only praises the Air Force's decision). It lacks a clear statement of personal involvement as required by Criterion 2."
    },
    {
      "document_id": "1313",
      "label": "0",
      "explanation": "Senator Lieberman expresses frustration over the House's refusal to vote on a D.C. voting rights bill. This is general political commentary with no achieved outcome."
    },
    {
      "document_id": "133",
      "label": "0",
      "explanation": "Senator Kerry criticizes the administration's ports deal with Dubai. This is general commentary and criticism without any credit-claiming."
    },
    {
      "document_id": "2143",
      "label": "0",
      "explanation": "This release is a tribute to a deceased Washington state Democratic leader, which falls under condolences/tributes under Negative Clarification 3."
    },
    {
      "document_id": "3047",
      "label": "1",
      "explanation": "The Idaho Congressional delegation claims shared responsibility for writing to the USDA Secretary to request a potato purchase, which successfully resulted in the USDA announcing the purchase of up to 80 million pounds of potatoes to benefit Idaho growers."
    },
    {
      "document_id": "630",
      "label": "0",
      "explanation": "Senator Dodd comments on the proposed defense budget's impact on Connecticut but does not claim personal credit for securing these funds, representing general commentary on a budget proposal."
    },
    {
      "document_id": "490",
      "label": "0",
      "explanation": "Senator Webb criticizes the Bush administration's foreign policy on Iran. This is general commentary/criticism and is not credit-claiming."
    },
    {
      "document_id": "4344",
      "label": "0",
      "explanation": "Senator Salazar announces his support for a compromise on the Patriot Act, but does not claim personal credit for authoring or securing the compromise, representing general policy commentary."
    },
    {
      "document_id": "1060",
      "label": "1",
      "explanation": "Senator Nelson claims shared credit for the inclusion of his co-sponsored Small Business Health Care Amendment in the passed S-CHIP reauthorization, which serves as a positive legislative milestone aimed at helping small business employees in Nebraska."
    },
    {
      "document_id": "299",
      "label": "0",
      "explanation": "Senator Alexander expresses gratitude for being named a 'Hero of the Taxpayer' by a third-party group based on his voting record. This does not announce a concrete, achieved outcome or a particularized benefit he personally secured for his constituency."
    },
    {
      "document_id": "214",
      "label": "0",
      "explanation": "This text is a memorial statement honoring those who died at Pearl Harbor, which falls under tributes/advertising (Negative Clarification 3)."
    },
    {
      "document_id": "773",
      "label": "0",
      "explanation": "Senator McCaskill announces the passage of a resolution honoring the late Senator Thomas F. Eagleton. This is a tribute to a deceased individual, which falls under advertising/tributes (Negative Clarification 3)."
    }
  ]
}

